class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final coordinates back to position
        # Position = row * n + col
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[i][val] = number of ways to assign values to positions 0 to i 
        # where arr1[i] = val
        # We'll use a dictionary for current state

        # Initialize for first position
        dp = {}
        for val in range(nums[0] + 1):
            dp[val] = 1

        # Process each subsequent position
        for i in range(1, n):
            new_dp = {}

            # For each possible value of arr1[i]
            for val1 in range(nums[i] + 1):
                # Find the minimum value arr1[i-1] can take
                # From non-decreasing: arr1[i-1] <= val1
                # From arr2 non-increasing: arr1[i] >= arr1[i-1] + (nums[i] - nums[i-1])
                # So arr1[i-1] <= val1 - (nums[i] - nums[i-1])

                # If nums[i] > nums[i-1], we have a constraint
                if nums[i] > nums[i-1]:
                    constraint = nums[i] - nums[i-1]
                    max_prev_val = val1 - constraint
                else:
                    max_prev_val = val1

                # max_prev_val is the maximum value arr1[i-1] can take
                # arr1[i-1] can be from 0 to max_prev_val
                ways = 0
                for prev_val in range(max_prev_val + 1):
                    if prev_val in dp:
                        ways = (ways + dp[prev_val]) % MOD

                if ways > 0:
                    new_dp[val1] = ways

            dp = new_dp

        # Sum all possibilities for the last position
        result = 0
        for val in dp:
            result = (result + dp[val]) % MOD

        return result

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store count of each color for each player
        player_color_count = {}

        # Process each pick
        for player, color in pick:
            if player not in player_color_count:
                player_color_count[player] = {}
            player_color_count[player][color] = player_color_count[player].get(color, 0) + 1

        # Count winning players
        winning_count = 0

        for player in range(n):
            # Find maximum count of any single color for this player
            max_count = max(player_color_count.get(player, {}).values()) if player in player_color_count else 0

            # Player i wins if they have at least i+1 balls of same color
            if max_count >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def calculate_rows_flips():
            flips = 0
            for row in grid:
                # For each row, check symmetric pairs
                for i in range(n // 2):
                    j = n - 1 - i
                    if row[i] != row[j]:
                        flips += 1
            return flips

        def calculate_cols_flips():
            flips = 0
            for col in range(n):
                # For each column, check symmetric pairs
                for i in range(m // 2):
                    j = m - 1 - i
                    if grid[j][col] != grid[i][col]:
                        flips += 1
            return flips

        # Return minimum flips needed for rows or columns
        return min(calculate_rows_flips(), calculate_cols_flips())

