def solve():
    N, D = map(int, input().split())
    x_coords = []
    y_coords = []

    for _ in range(N):
        x, y = map(int, input().split())
        x_coords.append(x)
        y_coords.append(y)

    if D == 0:
        if N == 1:
            return 1
        else:
            return 0

    # Sort y coordinates
    y_sorted = sorted(y_coords)

    # Precompute sum of distances to y-coordinates
    def get_sum_y(y_val):
        return sum(abs(y_val - y) for y in y_sorted)

    # Find the range of x values to check
    min_x, max_x = min(x_coords), max(x_coords)
    x_start = min_x - D
    x_end = max_x + D

    # We only need to check x values at the coordinate points and their immediate neighbors
    # because the function is piecewise linear
    x_values_to_check = set()

    # Add all x coordinates
    for x in x_coords:
        x_values_to_check.add(x)

    # Add values around each coordinate within D distance
    for x in x_coords:
        for dx in range(-D, D + 1):
            x_val = x + dx
            if x_val >= x_start and x_val <= x_end:
                x_values_to_check.add(x_val)

    # Convert to sorted list
    x_values_to_check = sorted(x_values_to_check)

    total = 0

    for x in x_values_to_check:
        sum_x_dist = sum(abs(x - x_coord) for x_coord in x_coords)

        if sum_x_dist > D:
            continue

        remaining = D - sum_x_dist

        # Find valid y range
        # Binary search for left boundary
        left, right = min(y_coords) - remaining, min(y_coords)
        while left <= right:
            mid = (left + right) // 2
            if get_sum_y(mid) <= remaining:
                right = mid - 1
            else:
                left = mid + 1
        left_bound = left

        # Binary search for right boundary
        left2, right2 = max(y_coords), max(y_coords) + remaining
        while left2 <= right2:
            mid = (left2 + right2 + 1) // 2
            if get_sum_y(mid) <= remaining:
                left2 = mid + 1
            else:
                right2 = mid - 1
        right_bound = right2

        if left_bound <= right_bound:
            y_count = right_bound - left_bound + 1
            total += y_count

    return total

